// Some portions generated by Claude

// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	repositoryPageUrl,
	serverBaseUrl,
	uniqueRepositoryId,
	workbenchBaseUrl
} = require('./workbench-test-helpers.js');

// Milestone M6 of .agent/execplans/workbench-app-shell-and-critique-fixes-20260930.md: safe destructive actions.
const REPOSITORY_ID = uniqueRepositoryId('workbench-destructive');

test.describe.configure({ mode: 'serial' });

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID, { graphs: ['bsbm', 'spl'] });
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test('Remove with every field empty shows the server error in an error callout', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'remove'), { waitUntil: 'domcontentloaded' });
	// The button stays disabled while every field is empty (plan task M6.5), so post the empty form directly.
	await expect(page.locator('#remove-form button[type="submit"]')).toBeDisabled();
	await page.locator('#remove-form').evaluate((form) => form.submit());
	const error = page.locator('#remove-form .workbench-callout--error');
	await expect(error).toBeVisible();
	await expect(error).toContainText('No values');
});

test('Deleting a saved query asks in a dialog that works with the keyboard alone', async ({ page, browserName }) => {
	// Safari moves focus to buttons with Option+Tab.
	const nextControl = browserName === 'webkit' ? 'Alt+Tab' : 'Tab';
	await page.setViewportSize({ width: 1440, height: 900 });
	const queryName = `destructive-dialog-${Date.now()}`;
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'), { waitUntil: 'domcontentloaded' });
	const editor = page.locator('.CodeMirror').first();
	await editor.waitFor();
	await editor.evaluate((element) => element.CodeMirror.setValue('ASK { ?s ?p ?o }'));
	await page.locator('#save-query-toggle').press('Enter');
	await page.locator('#query-name').fill(queryName);
	await page.evaluate(() => window.workbench.query.handleNameChange());
	await page.locator('#save').click();
	await expect(page.locator('#save-feedback')).toContainText('Query saved.');

	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'saved-queries'), { waitUntil: 'domcontentloaded' });
	const row = page.locator('.saved-query-row').filter({ has: page.locator('h2', { hasText: queryName }) });
	await row.locator('.saved-query-delete').focus();
	await page.keyboard.press('Enter');
	const dialog = page.getByRole('dialog', { name: 'Delete saved query?' });
	await expect(dialog).toBeVisible();
	await expect(dialog.getByRole('button', { name: 'Cancel' })).toBeFocused();
	await page.keyboard.press('Escape');
	await expect(dialog).toHaveCount(0);
	await expect(row).toHaveCount(1);

	await row.locator('.saved-query-delete').focus();
	await page.keyboard.press('Enter');
	await expect(dialog.getByRole('button', { name: 'Cancel' })).toBeFocused();
	await page.keyboard.press(nextControl);
	await expect(dialog.getByRole('button', { name: 'Delete' })).toBeFocused();
	await page.keyboard.press('Enter');
	await expect(page.locator('.saved-query-row').filter({ has: page.locator('h2', { hasText: queryName }) })).toHaveCount(0);
});

test('Delete repository waits for a chosen repository and its typed id', async ({ page, request }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	const doomed = uniqueRepositoryId('workbench-delete-me');
	await createSeededRepository(request, serverBaseUrl(), doomed, { graphs: [] });
	try {
		await page.goto(`${workbenchBaseUrl()}/repositories/NONE/delete`, { waitUntil: 'domcontentloaded' });
		const select = page.locator('#delete-form select#id');
		const action = page.locator('#delete-form button[type="submit"]');
		await expect(select.locator('option').first()).toHaveText('Choose a repository');
		await expect(select).toHaveValue('');
		await expect(action).toBeDisabled();
		await select.selectOption({ index: 1 });
		await expect(action).toBeEnabled();

		await page.goto(`${workbenchBaseUrl()}/repositories/NONE/delete?id=${encodeURIComponent(doomed)}`,
			{ waitUntil: 'domcontentloaded' });
		await expect(select).toHaveValue(doomed);
		await expect(action).toHaveText('Delete repository…');
		await action.click();
		const dialog = page.getByRole('dialog', { name: `Delete repository ${doomed}?` });
		const confirm = dialog.getByRole('button', { name: 'Delete repository' });
		await expect(confirm).toBeDisabled();
		await dialog.getByRole('button', { name: 'Cancel' }).click();
		expect((await request.get(`${serverBaseUrl()}/repositories/${doomed}/size`)).ok()).toBe(true);

		await action.click();
		await dialog.getByRole('textbox').fill(doomed);
		await expect(confirm).toBeEnabled();
		await confirm.click();
		await expect(page).toHaveURL(/\/repositories\/NONE\/repositories(?:[?#]|$)/);
		expect((await request.get(`${serverBaseUrl()}/repositories/${doomed}/size`)).ok()).toBe(false);
	} finally {
		await deleteRepository(request, serverBaseUrl(), doomed).catch(() => {});
	}
});

/** The repository's namespace for a prefix, read through the server's REST API ('' when it has none). */
async function namespaceOf(request, prefix) {
	const response = await request.get(`${serverBaseUrl()}/repositories/${encodeURIComponent(REPOSITORY_ID)}/namespaces/${prefix}`);
	return response.ok() ? (await response.text()).trim() : '';
}

test('Namespaces start with empty fields, edit in the row and delete only after confirmation', async ({ page, request }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'namespaces'), { waitUntil: 'domcontentloaded' });
	const card = page.locator('#namespaces-results');
	await expect(card.locator('.workbench-browse-card__header h2')).toHaveText('Namespaces');
	const inputs = page.locator('#workbench-page-surface input[type="text"], #workbench-page-surface input[type="search"]');
	await expect(inputs).toHaveCount(1);
	await expect(inputs).toHaveValue('');
	const prefixes = await card.locator('tbody tr td:first-child').allInnerTexts();
	expect(prefixes.length).toBeGreaterThan(5);
	expect(prefixes).toEqual([...prefixes].sort());

	await card.locator('#namespaces-filter').fill('foaf');
	await expect(card.locator('tbody tr')).toHaveCount(1);
	await card.locator('#namespaces-filter').fill('');

	const dc = card.locator('tbody tr').filter({ has: page.locator('td:first-child', { hasText: /^dc$/ }) });
	await dc.getByRole('button', { name: 'Edit dc' }).click();
	const editing = card.locator('tbody tr.workbench-namespace-edit');
	await expect(editing.getByRole('textbox', { name: 'Prefix' })).toHaveValue('dc');
	await expect(editing.getByRole('textbox', { name: 'Prefix' })).toBeFocused();
	await editing.getByRole('textbox', { name: 'Prefix' }).fill('dc11');
	await editing.getByRole('button', { name: 'Save' }).click();
	await expect(card.locator('td:first-child', { hasText: /^dc11$/ })).toHaveCount(1);
	expect(await namespaceOf(request, 'dc11')).toBe('http://purl.org/dc/elements/1.1/');
	expect(await namespaceOf(request, 'dc')).toBe('');

	await card.getByRole('button', { name: 'Add namespace' }).click();
	const added = card.locator('tbody tr').first();
	await added.getByRole('textbox', { name: 'Prefix' }).fill('tst');
	await added.getByRole('textbox', { name: 'Namespace' }).fill('http://example.org/test#');
	await added.getByRole('button', { name: 'Save' }).click();
	await expect(card.locator('td:first-child', { hasText: /^tst$/ })).toHaveCount(1);
	expect(await namespaceOf(request, 'tst')).toBe('http://example.org/test#');

	const tst = card.locator('tbody tr').filter({ has: page.locator('td:first-child', { hasText: /^tst$/ }) });
	await tst.getByRole('button', { name: 'Delete tst' }).click();
	const dialog = page.getByRole('dialog', { name: 'Delete prefix tst?' });
	await expect(dialog).toContainText('http://example.org/test#');
	await dialog.getByRole('button', { name: 'Cancel' }).click();
	expect(await namespaceOf(request, 'tst')).toBe('http://example.org/test#');
	await tst.getByRole('button', { name: 'Delete tst' }).click();
	await dialog.getByRole('button', { name: 'Delete prefix' }).click();
	await expect(card.locator('td:first-child', { hasText: /^tst$/ })).toHaveCount(0);
	expect(await namespaceOf(request, 'tst')).toBe('');
});

test('Remove counts the matching statements as you type and confirms before removing them', async ({ page, request }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'remove'), { waitUntil: 'domcontentloaded' });
	const form = page.locator('#remove-form');
	const action = form.locator('button[type="submit"]');
	await expect(form.locator('#subj')).toHaveAttribute('placeholder', 'Any subject');
	await expect(form.locator('select#context option').first()).toHaveText('Any graph');
	await expect(action).toBeDisabled();

	await form.locator('#subj').fill('<http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/instances/dataFromProducer1/Product1>');
	const status = form.locator('#remove-count');
	await expect(status).toHaveText(/^\d+ statements match$/);
	const matches = Number((await status.innerText()).match(/^(\d+)/)[1]);
	expect(matches).toBeGreaterThan(1);
	await expect(action).toHaveText(`Remove ${matches} statements…`);
	await expect(action).toBeEnabled();

	await form.locator('#pred').fill('<not an iri');
	await expect(form.locator('#pred-error')).toContainText('predicate');
	await expect(action).toBeDisabled();
	await form.locator('#pred').fill('');
	await expect(action).toHaveText(`Remove ${matches} statements…`);

	const before = await sizeOf(request);
	await action.click();
	const dialog = page.getByRole('dialog', { name: `Remove ${matches} statements?` });
	await dialog.getByRole('button', { name: 'Cancel' }).click();
	expect(await sizeOf(request)).toBe(before);
	await action.click();
	await dialog.getByRole('button', { name: 'Remove statements' }).click();
	await expect(page).toHaveURL(/\/summary$/);
	expect(await sizeOf(request)).toBe(before - matches);
});

/** The number of statements in the repository or one of its graphs, read through the server's REST API. */
async function sizeOf(request, context) {
	const query = context === undefined ? '' : `?context=${encodeURIComponent(context)}`;
	const response = await request.get(`${serverBaseUrl()}/repositories/${encodeURIComponent(REPOSITORY_ID)}/size${query}`);
	return Number((await response.text()).trim());
}

// Keep this test last: it clears the repository.
test('Clear lists the graphs with their sizes and asks before clearing a graph or everything', async ({ page, request }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	const spl = '<http://example.org/graph/spl>';
	const bsbm = '<http://example.org/graph/bsbm>';
	await page.goto(`${repositoryPageUrl(REPOSITORY_ID, 'clear')}?context=${encodeURIComponent(spl)}`,
		{ waitUntil: 'domcontentloaded' });
	const target = page.locator('#clear-form select[name="context"]');
	await expect(target).toHaveValue(spl);
	const options = await target.locator('option').allInnerTexts();
	expect(options[0]).toMatch(/^Entire repository — [\d,]+ statements$/);
	expect(options[1]).toMatch(/^Default graph — [\d,]+ statements?$/);
	expect(options.slice(2)).toEqual([
		expect.stringMatching(/^http:\/\/example\.org\/graph\/bsbm — [\d,]+ statements$/),
		expect.stringMatching(/^http:\/\/example\.org\/graph\/spl — [\d,]+ statements$/)
	]);
	const action = page.locator('#clear-form button[type="submit"]');
	await expect(action).toHaveText('Clear graph…');

	const bsbmSize = await sizeOf(request, bsbm);
	await action.click();
	const graphDialog = page.getByRole('dialog', { name: 'Clear graph?' });
	await expect(graphDialog).toContainText('http://example.org/graph/spl');
	await graphDialog.getByRole('button', { name: 'Clear graph' }).click();
	await expect(page).toHaveURL(/\/summary$/);
	expect(await sizeOf(request, spl)).toBe(0);
	expect(await sizeOf(request, bsbm)).toBe(bsbmSize);

	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'clear'), { waitUntil: 'domcontentloaded' });
	await expect(target).toHaveValue('');
	await expect(action).toHaveText('Clear entire repository…');
	await action.click();
	const everything = page.getByRole('dialog', { name: 'Clear entire repository?' });
	await expect(everything).toContainText(`from ${REPOSITORY_ID}`);
	const confirm = everything.getByRole('button', { name: 'Clear repository' });
	await expect(confirm).toBeDisabled();
	await everything.getByRole('button', { name: 'Cancel' }).click();
	expect(await sizeOf(request)).toBeGreaterThan(0);

	await action.click();
	await expect(confirm).toBeDisabled();
	await everything.getByRole('textbox').fill(REPOSITORY_ID);
	await expect(confirm).toBeEnabled();
	await confirm.click();
	await expect(page).toHaveURL(/\/summary$/);
	expect(await sizeOf(request)).toBe(0);
});
